using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBungeeDemolition {
public sealed class BungeeProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBungee")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.BungeeProbe",false);UnityEditor.SessionState.SetBool("LWS.BungeeProbe",false);
#endif
 if(run){var g=new GameObject("Bungee complete four-AI physical match acceptance");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<BungeeProbe>();}}
 BungeeMatch m;string folder;int errors;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s);}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("BungeeEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<BungeeMatch>("TruckBungeeDemolition");m=FindAnyObjectByType<BungeeMatch>();yield return null;m.setup.count=4;m.NormalizeSetup();m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);Check(m.StartMatch(),"four independent Easy/Normal/Hard AI bays start without controllers");Time.timeScale=4;float end=Time.realtimeSinceStartup+240,next=0;bool paused=false;int round=0;var physical=new int[4];var totals=new int[4];while(!m.Finished&&Time.realtimeSinceStartup<end){for(int i=0;i<4;i++){physical[i]=Mathf.Max(physical[i],m.bays[i].Collapses);totals[i]=Mathf.Max(totals[i],m.total[i]);}if(!paused&&m.Phase==BungeePhase.Demolition&&m.Clock<56){paused=true;m.Pause();var p=m.bays[0].truck.body.position;float clock=m.Clock;int score=m.bays[0].Score;yield return new WaitForSecondsRealtime(.2f);Check(m.Paused&&p==m.bays[0].truck.body.position&&clock==m.Clock&&score==m.bays[0].Score,"pause preserves actual flight, score, rope and active clock");m.Resume();Time.timeScale=4;}if(m.CompletedRounds!=round){round=m.CompletedRounds;report.AppendLine("ROUND "+round+" totals="+string.Join(",",m.total)+" collapses="+string.Join(",",Array.ConvertAll(m.bays,b=>b.Collapses))+" recoveries="+string.Join(",",Array.ConvertAll(m.bays,b=>b.Recoveries)));}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",report+"LIVE round="+m.Round+" phase="+m.Phase+" clock="+m.Clock+" scores="+string.Join(",",Array.ConvertAll(m.bays,b=>b.Score))+" positions="+string.Join(" | ",Array.ConvertAll(m.bays,b=>b.truck.body.position.ToString("F1")))+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}Check(m.Finished&&m.Winner>=0&&m.CompletedRounds>=3,"complete physical three-round four-AI match, including real tiebreak if needed");for(int i=0;i<4;i++)Check(physical[i]>0&&m.total[i]>0,"AI physically damages/collapses tower without hidden score slot="+i+" total="+m.total[i]);Check(m.FinaleScoreChanges==0,"all automatic finales preserve locked scores");Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"one listener");m.SetupScreen();Check(m.StartMatch()&&m.Round==1&&Array.TrueForAll(m.total,x=>x==0),"rematch clears totals and resets four towers/cables while retaining configuration");report.AppendLine("ERRORS="+errors+". Native four-bay Core-Collapse/PhysX match, no hardware/human playtest or player-render performance claim.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("BUNGEE_PROBE_COMPLETE "+report);m.SetupScreen();Time.timeScale=1;Application.logMessageReceived-=Error;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void OnDestroy(){Application.logMessageReceived-=Error;Time.timeScale=1;}
#endif
}
}
